    if not raw_path:
        return None
    archive_path = _update.Path(raw_path)
    if not archive_path.is_absolute():
        return {
            "kind": "local_archive",
            "archive_type": "wheel" if archive_path.suffix.lower() == ".whl" else "archive",
            "url": _update._credential_safe_url(raw_url),
            "path": str(archive_path),
            "path_exists": False,
