            _verified_newer_guard_daemon(
                context.guard_home,
                minimum_version=current_version,
            )
            if context is not None
            else None
        )
        if newer_runtime is not None:
            payload["daemon_refresh"] = newer_runtime
            payload["runtime_artifact_owner"] = "newer_runtime"
