function pyTokens(source) {
 const tokens=[];
 function scan(start,end,expression=false) {
  let i=start;
  while(i<end){
   const c=source[i];
   if(/\s/.test(c)){i++;continue;}
   if(c==="#"){const k=source.indexOf("\n",i);i=k<0?end:Math.min(k,end);continue;}
   let prefix="",q=i;
   const p=source.slice(i).match(/^(?:[rRuUbBfF]{1,2})(?=['"])/);
   if(p){prefix=p[0];q=i+prefix.length;}
   if(source[q]==="'"||source[q]==='"'){
    const quote=source[q],triple=source.slice(q,q+3)===quote.repeat(3),n=triple?3:1,body=q+n;
    let j=body;
    while(j<end){if(source[j]==="\\"){j+=2;continue;}if(source.slice(j,j+n)===quote.repeat(n))break;j++;}
    if(j>=end)throw Error("unterminated string at "+i);
    tokens.push({kind:"string",start:i,end:j+n,text:source.slice(i,j+n),expression});
    if(/[fF]/.test(prefix)){
     let k=body;
     while(k<j){
      if(source[k]==="{"&&source[k+1]!=="{"){
       let z=k+1,depth=0,quoteMode=null,closing=-1;
       while(z<j){
        if(quoteMode){if(source[z]==="\\"){z+=2;continue;}if(source.slice(z,z+quoteMode.length)===quoteMode){z+=quoteMode.length;quoteMode=null;continue;}z++;continue;}
        if(source[z]==="'"||source[z]==='"'){quoteMode=source.slice(z,z+3)===source[z].repeat(3)?source[z].repeat(3):source[z];z+=quoteMode.length;continue;}
        if("([{".includes(source[z]))depth++;
        else if(source[z]==="}"&&depth===0){closing=z;break;}
        else if(")]}".includes(source[z]))depth--;
        z++;
       }
       if(closing<0)throw Error("unterminated f-expression");
       scan(k+1,closing,true);k=closing+1;
      } else if((source[k]==="{"||source[k]==="}")&&source[k+1]===source[k])k+=2;
      else k++;
     }
    }
    i=j+n;continue;
   }
   if(/[A-Za-z_]/.test(c)){let j=i+1;while(j<end&&/[A-Za-z0-9_]/.test(source[j]))j++;tokens.push({kind:"id",start:i,end:j,text:source.slice(i,j),expression});i=j;continue;}
   tokens.push({kind:"punct",start:i,end:i+1,text:c,expression});i++;
  }
 }
 scan(0,source.length);return tokens.sort((a,b)=>a.start-b.start||b.end-a.end);
}

