function updateTopFunctions(content, pyTokens) {
 const tokens=pyTokens(content);
 const starts=[];
 for(let i=0;i<tokens.length;i++){
  const token=tokens[i];
  if(token.expression||token.text!=="def")continue;
  const lineStart=content.lastIndexOf("\n",token.start-1)+1;
  if(token.start===lineStart)starts.push({name:tokens[i+1].text,start:token.start});
 }
 const deferred=content.lastIndexOf("# Bind the facade after definitions so either module can be imported first.");
 return starts.map((start,i)=>{
  const end=i+1<starts.length?starts[i+1].start:deferred;
  if(end<start.start)throw Error("function end");
  const value=content.slice(start.start,end).trimEnd()+"\n";
  let depth=0,headerEnd=0;
  for(const token of pyTokens(value)){
   if(token.kind!=="punct"||token.expression)continue;
   if("([{".includes(token.text))depth++;
   else if(")]}".includes(token.text))depth--;
   else if(token.text===":"&&depth===0){headerEnd=value.indexOf("\n",token.end)+1;break;}
